    { id: 12, title: "后宫" },
    { id: 13, title: "女主" },
    { id: 14, title: "古风" },
    { id: 15, title: "连载" },
    { id: 16, title: "完结" }
];

list.forEach(item => {
    let Url = 'https://m.dumanwu.com/data/sort,';
    let option = {"body":"s="+item.id+"&p={{page}}","method":"POST"};
    let url = Url + JSON.stringify(option);
    push(item.title, url, 1, 0.25); 
});

JSON.stringify(sort)

