source.exploreUrl:
@js: 
个人中心 = 1 

js = (cid, genre, gender) => `@js:
source.bookSourceUrl.split("#")[0] + "/reading/bookapi/new_category/landing/v/?" + [
    "category_id=${cid}",
    "limit=20",
    "offset=" + (page - 1),
    "gender=${gender}",
    "genre=${genre}"
  ].join("&")`

readHistory = (path) => `@js:
let ck = "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : source.getLoginInfoMap()['手动登录Token'])
"/multi-detail?book_id=" + getBookId(java.ajax('https://reading.snssdk.com/reading/bookapi/read_history/list/v/?aid=1967,{"headers":{"Cookie":"' + ck + '"}}'), page-1)`

obj = (title, url, type, type1) => ({
  title: title,
  url: url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: type
  }
})

arr = []
java.longToast("请稍等，发现列表正在热更新！")
index=[0, 1, 2]
for (let i of index) {
  // java.toast(i)
  let type = i
  $ = JSON.parse(java.ajax(java.log(source.bookSourceUrl.split("#")[0] + "/reading/bookapi/new_category/front/v/?" + [
      "update_version_code=58932",
      "distinct_style=1",
      "new_category_tab=" + i
    ].join("&")
  ))).data.category_tab_data
  cate = []
  cate.push(obj(
    "====== " + $.tab_name + " ======", "", 1
  ))
  $.cell_data.forEach((c) => {
    gender_1 = (type == 0 || type == 1) ? type : 1;
    genre_1 = type == 3 ? 1 : type == 5 ? 110 : type == 6 ? 130 : 0;
    cate.push(obj(
      c.cell_name,
      js(c.atom_data[0].category_data.category_id, genre_1, gender_1),
      1
    ))
    for (j = 2; j < 5; j++) {
      c.atom_data.slice(1).forEach((a) => {
        d = a.category_data
        if (d.name.length == j) {
          cate.push(obj(d.name, js(d.category_id, genre_1, gender_1), -1))
        }
      })
    }
  })
  arr = cate.concat(arr)
}

let book_shelf_url = 'https://fanqienovel.com/reading/bookapi/bookshelf/info/v:version/?aid=1967&iid=0&version_code=57700&update_version_code=57700'
let book_shelf_info = JSON.parse(java.ajax(book_shelf_url + ', ' + JSON.stringify({
  headers: {
    'Cookie': "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap() ? source.getLoginInfoMap() : {})['手动登录Token']),
  }
})))

java.log(JSON.stringify(book_shelf_info))

let username
if (book_shelf_info.code != 0) {
  个人中心 = 0
  // source.setVariable('{}')
} else {
  let uinfo = java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({ headers: { Cookie: "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap() ? source.getLoginInfoMap() : {})['手动登录Token']) }}))
  let arrB = []
  for (let i of book_shelf_info.data.book_shelf_info) {
    arrB.push(i.book_id)
  }
  uinfo = JSON.parse(uinfo)
  write_config('bookshelf.' + uinfo.data.id, arrB)
  write_config('userinfo', { name: uinfo.data.name, userid: uinfo.data.id })
  username = uinfo.data.name
}

let gro = []
push = (title, url, type) => gro.push({
  title: title,
  url: url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: type
  }
});

let sArr = []

if (个人中心) {
  let groups_bookids = {
    "未分组": []
  }
  book_shelf_info.data.book_shelf_info.forEach(i => {
    if (!groups_bookids[i.group_name ? i.group_name : "未分组"]) groups_bookids[i.group_name] = []
    groups_bookids[i.group_name ? i.group_name : "未分组"].push(i.book_id)
  })

  Object.keys(groups_bookids).forEach(k => {
    var multi_detail_post_body = {
      data: {
        book_shelf_info: []
      }
    }
    groups_bookids[k].forEach(i => multi_detail_post_body.data.book_shelf_info.push({ book_id: String(i), item_id: '0' }))
    // var multi_detail_group_url = `https://fanqienovel.com/api/bookshelf/multidetail,${JSON.stringify(multi_detail_post_body)}`
    // var book_ids = getBookId(JSON.stringify(multi_detail_post_body)).join(",")
    push(k, "https://fanqienovel.com/fqbookshelf/groupName/" + k, 0.4)
  })
  if (Object.keys(groups_bookids).length % 2 != 0) push("占位", "", 0.4)
  // java.log(JSON.stringify(gro, null, 2))
  sArr.push(obj(username + '的个人中心', '', 1))
  // sArr.push(obj('首页推荐', "https://fanqienovel.com/tab/0", 0.4))
  // sArr.push(obj('猜你喜欢', "https://fanqienovel.com/tab/1", 0.4))
  // sArr.push(obj('猜你喜欢', "https://fanqienovel.com/tab/1", 0.4))
  sArr.push(obj("我的书架", "https://fanqienovel.com/fqbookshelf", 1))

  sArr = sArr.concat(gro)
  // java.toast(JSON.stringify(sArr)) 
  sArr.push(obj("阅读历史", readHistory(), 1))
}

arr = sArr.concat(arr)
JSON.stringify(arr)

source.loginJs:
// 登录及登录检查
function login_(openBrowser, checkMode) {
    // java.removeCookie("snssdk.com")
    var cookie_ = String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap() ? source.getLoginInfoMap() : {})['手动登录Token']
    // java.toast(cookie_)
    if (cookie_ && cookie_ != "" && !checkMode) {
        if (!source.variableComment) {
            java.toast("请不要重复登录，请先退出登录！")
        } else {
            java.toast("您为填写token登录，请手动移除token后再次登录")
        }
        return false
    }
    if (openBrowser) {
        try {
            java.startBrowserAwait("https://fanqienovel.com/", "登录")
        } catch (e) {
            java.toast(e)
        }
    }
    // java.log("snssdk cookie: " + java.getCookie("snssdk.com") + "will be reomved")
    try {
        cookie.removeCookie("snssdk.com")
    } catch (e) {}
    // java.log(cookie)
    var cookie_ = "sessionid=" + String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap())['手动登录Token']
    let user
    let uid
    try {
      u = JSON.parse(java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({
        method: "GET",
        headers: {
          "Cookie": cookie_
        }
      }))).data
      uid = u.id
      user = u.name
     } catch (e) {java.log(e)}
    if (!cookie_ || cookie_ == "sessionid=" || !user) {
        java.toast("未获取到登录凭据，登录失败")
        return false
    }
    java.toast("欢迎 " + user + "\n登录成功！")
    let bookshelf_info = JSON.parse(java.ajax("https://fanqienovel.com/reading/bookapi/bookshelf/info/v:version/?aid=1967&iid=0&version_code=57700&update_version_code=57700," + JSON.stringify({
      method: "GET",
      headers: {
        "Cookie": cookie_
      }
    }))).data.book_shelf_info
    let arrB = []
    for (let i of bookshelf_info) {
      arrB.push(i.book_id)
    }
    write_config('userinfo', { name: user, userid: uid })
    write_config('bookshelf.' + uid, arrB)
    return true
}

function login() // 一定程度上加上这个函数能够支持更多的版本
{}

function l2(a, b) {
  try {
    login_(a, b)
  } catch (e) {
    java.log(e+"\n"+e.stack)
  }
}

// 取消登录
function logout() {
    cookie.removeCookie("fanqienovel.com");
    cookie.removeCookie("snssdk.com");
    if (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap() ? source.getLoginInfoMap() : {})['手动登录Token']) java.toast("请手动移除填写的Token")
    else java.toast("退出登录成功");
}

function logToken() {
  java.log(
    String(
      cookie.getKey(
        "fanqienovel.com",
        "sessionid"
      )
    ) ? String(
     cookie.getKey(
        "fanqienovel.com", 
        "sessionid"
      )
    ) : (
     source.getLoginInfoMap()
      ? source.getLoginInfoMap()
      : {}
    )['手动登录Token']
  )
  java.toast("登录Token已打印到日志，请妥善保管")
}

function tutorial() {
  java.longToast("\n手动登录token功能用于部分用户的跨端登录，不知道是什么的留空就行\n普通用户请使用下方的\"账号登录\"按钮登录自己的账号")
}

function seePush() {
  java.toast('当前模式: ' + pushTrans[read_config('push_mode').index])
}

function changePush(mode) {
  if (typeof mode === 'undefined') {
    return java.toast('INVALID_ARGUMENT')
  }
  write_config('push_mode', { index: mode, action: pushModes[mode] })
  seePush()
}

function t() {
  let gc = ["(*^ω^*)", "(=^▽^=)", "(。’▽’。)♡", "٩(๑´0`๑)۶", "喵", "你好？", "逢考必过！", "早ﾉ☀"]
  rnd = Math.floor(Math.random() * 100)
  if (typeof gc[rnd] != "undefined") {
    java.longToast(gc[rnd])
  } else {
    let res = JSON.parse(
      java.ajax("https://v1.hitokoto.cn")
    )
    java.longToast(res.hitokoto)
  }
}

